// Input Validation + Classification por keywords (sin diccionarios rígidos).
const body = $input.item.json.body || $input.item.json;
const session_id = body.session_id || ('session_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8));
const query = String(body.query || '').trim();
const max_results = Math.min(parseInt(body.max_results) || 4, 10);

if (!query) throw new Error('INVALID_INPUT: query is required');

const TYPES = {
  laptop:     { keywords: ['laptop','notebook','portatil','macbook','ultrabook'],                 category_slug: 'computers' },
  smartphone: { keywords: ['celular','smartphone','iphone','android','telefono','movil'],         category_slug: 'phones' },
  monitor:    { keywords: ['monitor','pantalla','display','tv','television'],                     category_slug: 'displays' },
  audio:      { keywords: ['auricular','headset','altavoz','parlante','speaker','airpod'],        category_slug: 'audio' },
  accessory:  { keywords: ['cargador','cable','funda','adaptador','soporte','mouse','teclado'],   category_slug: 'accessories' }
};
const BRANDS = ['apple','samsung','xiaomi','sony','lg','asus','dell','hp','lenovo','acer','huawei','oneplus','jbl','bose','sennheiser','logitech','razer'];

const queryLower = query.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const tokens = queryLower.split(/\s+/).filter(Boolean);

// Hints de precio en lenguaje natural
let price_min = null, price_max = null;
const pmaxM = query.match(/(?:menos\s*de|hasta|under|<)\s*\$?(\d{2,6})/i);
if (pmaxM) price_max = parseInt(pmaxM[1], 10);
const pminM = query.match(/(?:mas\s*de|m\u00e1s\s*de|desde|over|>)\s*\$?(\d{2,6})/i);
if (pminM) price_min = parseInt(pminM[1], 10);

let detected_type = null, category_slug = null;
for (const [type, conf] of Object.entries(TYPES)) {
  if (tokens.some(t => conf.keywords.includes(t))) { detected_type = type; category_slug = conf.category_slug; break; }
}
const brand_hit = tokens.find(t => BRANDS.includes(t)) || null;
const intent = detected_type ? 'category_search' : (brand_hit ? 'brand_search' : 'free_text');

return [{ json: {
  session_id, query, query_lower: queryLower, tokens, max_results,
  classification: { type: detected_type, category_slug, brand: brand_hit, price_min, price_max, has_price_filter: price_min !== null || price_max !== null, intent },
  started_at: new Date().toISOString()
}}];

// Pre-filter: stock + rango de precios + ranking por marca.
// Materializa proxies de nodos previos (workaround de timeout del Task Runner).
const ctx = JSON.parse(JSON.stringify($('Validate & Classify').item.json));
const raw = JSON.parse(JSON.stringify($input.item.json));
const products = Array.isArray(raw) ? raw : (raw.data || raw.items || []);
const cls = ctx.classification;

const toPrice = (p) => p.prices && p.prices.price ? parseInt(p.prices.price, 10) / 100 : 0;

const filtered = products.filter(p => {
  if (p.is_in_stock === false) return false;
  const price = toPrice(p);
  if (cls.price_max !== null && price > cls.price_max) return false;
  if (cls.price_min !== null && price < cls.price_min) return false;
  return true;
});

const ranked = cls.brand
  ? [...filtered].sort((a, b) => {
      const aH = (a.name || '').toLowerCase().includes(cls.brand) ? 1 : 0;
      const bH = (b.name || '').toLowerCase().includes(cls.brand) ? 1 : 0;
      return bH - aH;
    })
  : filtered;

const top = ranked.slice(0, ctx.max_results);

const compact = top.map(p => ({
  id: p.id,
  name: p.name,
  price: p.prices && p.prices.price ? (parseInt(p.prices.price, 10) / 100).toFixed(2) : null,
  currency: p.prices && p.prices.currency_code ? p.prices.currency_code : 'USD',
  in_stock: p.is_in_stock !== false,
  description: ((p.short_description || p.description || '').replace(/<[^>]+>/g, '').slice(0, 160)),
  permalink: p.permalink,
  image: p.images && p.images[0] ? (p.images[0].thumbnail || p.images[0].src) : null
}));

return [{ json: {
  session_id: ctx.session_id,
  query: ctx.query,
  classification: cls,
  max_results: ctx.max_results,
  started_at: ctx.started_at,
  real_products: compact,
  real_count: compact.length,
  no_results: compact.length === 0
}}];

