// Normalize LLM Response — extrae mentioned_ids y reply_text
// independientemente del provider (OpenAI vs Anthropic).
const ctx = JSON.parse(JSON.stringify($('Pre-filter & Rank').item.json));
const raw = JSON.parse(JSON.stringify($input.item.json));
const provider = $env.LLM_PROVIDER || 'openai';

let content = '';
let parse_error = null;
let mentioned_ids = [];
let reply_text = '';

try {
  if (provider === 'openai') {
    content = raw.choices && raw.choices[0] && raw.choices[0].message ? raw.choices[0].message.content : '';
  } else if (provider === 'anthropic') {
    content = raw.content && raw.content[0] && raw.content[0].text ? raw.content[0].text : '';
  }
  const m = content.match(/\{[\s\S]*\}/);
  if (m) {
    const parsed = JSON.parse(m[0]);
    mentioned_ids = Array.isArray(parsed.mentioned_ids) ? parsed.mentioned_ids.map(String) : [];
    reply_text = String(parsed.reply_text || content);
  } else {
    reply_text = content;
    parse_error = 'no_json_block_found';
  }
} catch (e) {
  parse_error = e.message;
}

return [{ json: {
  ...ctx,
  llm_provider: provider,
  llm_raw: raw,
  llm_parsed: { mentioned_ids, reply_text },
  parse_error
}}];

// Anti-hallucination Post-Processor (4 sub-componentes):
//   1. Real-ID extractor: parsea IDs mencionados por el LLM.
//   2. Cross-check: marca como invalidos los IDs que no existen en la API real.
//   3. Stock & price verifier: detecta menciones inconsistentes (e.g. LLM dice
//      "esta disponible" pero la API dice out-of-stock; LLM menciona precios
//      lejos del valor real).
//   4. Hallucination scoring + sanitization: si el score >= threshold, reemplaza
//      la respuesta del LLM por una construida 100% desde datos reales.
const data = JSON.parse(JSON.stringify($input.item.json));
const real = data.real_products || [];
const llm = data.llm_parsed || { mentioned_ids: [], reply_text: '' };

const realIds = new Set(real.map(p => String(p.id)));
const byId = {};
for (const p of real) byId[String(p.id)] = p;

// (1) IDs mencionados
const mentioned = (llm.mentioned_ids || []).map(String);

// (2) Cross-check
const valid_ids = mentioned.filter(id => realIds.has(id));
const invalid_ids = mentioned.filter(id => !realIds.has(id));

// (3) Stock & price verifier
const replyLower = String(llm.reply_text || '').toLowerCase();
const stock_inconsistencies = [];
const price_inconsistencies = [];
for (const id of valid_ids) {
  const prod = byId[id];
  if (!prod) continue;
  const nameInReply = replyLower.includes((prod.name || '').toLowerCase());
  if (nameInReply && prod.in_stock === false) {
    stock_inconsistencies.push({ id, name: prod.name, llm_implied: 'available', actual: 'out_of_stock' });
  }
  if (nameInReply && prod.price) {
    const realPrice = parseFloat(prod.price);
    const priceMatches = (replyLower.match(/\$\s*([\d.,]+)/g) || []).map(s => parseFloat(s.replace(/[^\d.]/g, ''))).filter(n => !isNaN(n));
    if (priceMatches.length > 0) {
      const closeMatch = priceMatches.find(n => Math.abs(n - realPrice) / realPrice < 0.05);
      if (!closeMatch) price_inconsistencies.push({ id, name: prod.name, real_price: realPrice, mentioned_prices: priceMatches });
    }
  }
}

// (4) Score + sanitization
const total_mentioned = mentioned.length;
const total_issues = invalid_ids.length + stock_inconsistencies.length + price_inconsistencies.length;
const hallucination_score = total_mentioned === 0
  ? (total_issues > 0 ? 1 : 0)
  : Math.min(1, total_issues / Math.max(1, total_mentioned));

const HALLUCINATION_THRESHOLD = 0.3;
let final_reply = llm.reply_text || '';
let sanitized = false;
let sanitization_reason = null;

// i18n strings (controlled by BOT_LANG env var; defaults to 'en')
const lang = ($env.BOT_LANG || 'en').toLowerCase().startsWith('es') ? 'es' : 'en';
const T = {
  en: {
    no_results: (q) => `No products found for "${q}". Try a different search or category.`,
    found_n:    (n) => `Found ${n} product${n === 1 ? '' : 's'} that might interest you:`,
    out_of_stock: 'check availability'
  },
  es: {
    no_results: (q) => `No encontré productos que coincidan con "${q}". Probá con otra búsqueda o categoría.`,
    found_n:    (n) => `Encontré ${n} producto${n === 1 ? '' : 's'} que podrian interesarte:`,
    out_of_stock: 'consultar disponibilidad'
  }
}[lang];

if (data.no_results) {
  final_reply = T.no_results(data.query);
  sanitized = true;
  sanitization_reason = 'no_results';
} else if (data.parse_error) {
  sanitized = true;
  sanitization_reason = 'llm_parse_error';
} else if (hallucination_score >= HALLUCINATION_THRESHOLD || invalid_ids.length > 0) {
  sanitized = true;
  sanitization_reason = 'hallucination_threshold_exceeded';
}

if (sanitized && !data.no_results) {
  const top = real.slice(0, data.max_results);
  const lines = top.map((p, i) => `${i + 1}. **${p.name}** — ${p.currency} ${p.price}${p.in_stock ? '' : ' (' + T.out_of_stock + ')'}`).join('\n');
  final_reply = `${T.found_n(real.length)}\n\n${lines}`;
}

return [{ json: {
  ...data,
  final_reply,
  validation: {
    mentioned_count: total_mentioned,
    valid_count: valid_ids.length,
    invalid_count: invalid_ids.length,
    invalid_ids,
    stock_inconsistencies,
    price_inconsistencies,
    hallucination_score,
    sanitized,
    sanitization_reason,
    threshold: HALLUCINATION_THRESHOLD
  }
}}];

// Response Formatter — estructura final para el cliente.
const data = JSON.parse(JSON.stringify($input.item.json));
const latency_ms = Date.now() - new Date(data.started_at).getTime();

return [{ json: {
  session_id: data.session_id,
  reply: data.final_reply,
  products: data.real_products,
  meta: {
    query: data.query,
    intent: data.classification.intent,
    provider: data.llm_provider,
    latency_ms,
    result_count: data.real_count,
    validation: data.validation
  }
}}];
